// Guard: валідація запиту + захист ручних колонок 'План оплат'
// (Пріоритет = H = 8, Мій коментар = I = 9, 1-based). Google Sheets protection
// не блокує власника файлу, тому цей guard — РЕАЛЬНИЙ шар захисту.
// Блокується БУДЬ-ЯКИЙ режим запису (update/append/clear), чий діапазон
// ПЕРЕТИНАЄ колонки H:I (не лише явно їх називає). Читання (read) дозволене.
const body = $input.first().json.body || {};
const { sheetId, range, values, mode } = body;

const ALLOWED_MODES = ['update', 'append', 'clear', 'read', 'meta'];

if (!sheetId || !mode) {
  return [{ json: { error: true, code: 400, message: 'Missing required fields: sheetId, mode' } }];
}
if (!ALLOWED_MODES.includes(mode)) {
  return [{ json: { error: true, code: 400, message: `Unknown mode: ${mode}. Allowed: ${ALLOWED_MODES.join(', ')}` } }];
}
if (mode !== 'meta' && !range) {
  return [{ json: { error: true, code: 400, message: 'Missing required field: range' } }];
}

const PROTECTED_SHEET = 'План оплат';
const PROT_START = 8; // H (1-based)
const PROT_END = 9;   // I

function colToNum(letters) {
  let n = 0;
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64);
  return n;
}

// Повертає true, якщо діапазон (A1-нотація) перетинає колонки H:I 'Плану оплат'
function intersectsProtected(rangeStr) {
  const bang = rangeStr.indexOf('!');
  let sheetPart, cellPart;
  if (bang === -1) {
    // лише ім'я аркуша, без клітинок => весь аркуш
    sheetPart = rangeStr;
    cellPart = '';
  } else {
    sheetPart = rangeStr.slice(0, bang);
    cellPart = rangeStr.slice(bang + 1);
  }
  sheetPart = sheetPart.replace(/^'|'$/g, '');
  if (sheetPart !== PROTECTED_SHEET) return false;
  if (!cellPart) return true; // весь аркуш містить H:I

  // span колонок по обох кінцях діапазону
  const ends = cellPart.split(':');
  let minCol = Infinity, maxCol = -Infinity, anyLetters = false;
  for (const end of ends) {
    const m = end.match(/^\$?([A-Z]+)/);
    if (m) {
      anyLetters = true;
      const c = colToNum(m[1]);
      if (c < minCol) minCol = c;
      if (c > maxCol) maxCol = c;
    } else {
      // кінець без колонки (рядкова нотація, напр. "5" у "5:10") => всі колонки
      return true;
    }
  }
  if (!anyLetters) return true; // рядкова нотація => всі колонки
  if (ends.length === 1) maxCol = minCol; // одна клітинка/колонка
  // перетин інтервалів [minCol,maxCol] і [PROT_START,PROT_END]
  return minCol <= PROT_END && maxCol >= PROT_START;
}

const WRITE_MODES = ['update', 'append', 'clear'];
if (WRITE_MODES.includes(mode) && intersectsProtected(range)) {
  return [{ json: { error: true, code: 403, blocked: true, message: `Guard: діапазон '${range}' перетинає захищені колонки H:I (Пріоритет/Мій коментар) аркуша 'План оплат'. Будь-який запис/очищення (update/append/clear), що зачіпає ці колонки, заборонено на рівні коду проксі; читання дозволене. Ці колонки редагує лише користувачка вручну.` } }];
}

return [{ json: { error: false, sheetId, range, values, mode } }];

const { sheetId, range, values, mode } = $input.first().json;
const SPREADSHEET_ID = sheetId;
const encRange = range ? encodeURIComponent(range) : '';
let method, url, payload;

if (mode === 'update') {
  method = 'PUT';
  url = `https://sheets.googleapis.com/v4/spreadsheets/${SPREADSHEET_ID}/values/${encRange}?valueInputOption=RAW`;
  payload = { range, values };
} else if (mode === 'append') {
  method = 'POST';
  url = `https://sheets.googleapis.com/v4/spreadsheets/${SPREADSHEET_ID}/values/${encRange}:append?valueInputOption=RAW&insertDataOption=INSERT_ROWS`;
  payload = { range, values };
} else if (mode === 'clear') {
  method = 'POST';
  url = `https://sheets.googleapis.com/v4/spreadsheets/${SPREADSHEET_ID}/values/${encRange}:clear`;
  payload = {};
} else if (mode === 'read') {
  method = 'GET';
  url = `https://sheets.googleapis.com/v4/spreadsheets/${SPREADSHEET_ID}/values/${encRange}`;
  payload = {};
} else if (mode === 'meta') {
  method = 'GET';
  url = `https://sheets.googleapis.com/v4/spreadsheets/${SPREADSHEET_ID}?fields=properties.locale,properties.timeZone,sheets.properties`;
  payload = {};
}

return [{ json: { method, url, payload } }];

// Прокидаємо статус Google назовні: помилка Google -> не-200 відповідь вебхука
const r = $input.first().json;
const status = r.statusCode || 200;
let body = r.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = { raw: body }; }
}
if (body === undefined || body === null) body = {};
if (status >= 400) {
  if (typeof body === 'object' && !Array.isArray(body)) {
    body = { error: true, google_status: status, ...body };
  } else {
    body = { error: true, google_status: status, body };
  }
}
return [{ json: { _status: status, _body: body } }];

